-- Returns -> originating sale. Not part of the kit's referential-integrity script, but every
-- generated return matches a sale, and the link is what net-sales and return-rate analysis joins on.
ALTER TABLE store_returns ADD CONSTRAINT store_returns_sale_fkey FOREIGN KEY (sr_item_sk, sr_ticket_number) REFERENCES store_sales (ss_item_sk, ss_ticket_number);
